function TrendBadge({ value }: { value: number }) {
  const up = value >= 0;
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', gap: 3,
      fontSize: 11.5, fontWeight: 600,
      color: up ? '#059669' : '#DC2626',
      backgroundColor: up ? '#ECFDF5' : '#FEF2F2',
      padding: '2px 7px', borderRadius: 20,
    }}>
      <svg width="10" height="10" viewBox="0 0 10 10" fill="none">
        {up
          ? <path d="M5 8V2M2 5l3-3 3 3" stroke="#059669" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
          : <path d="M5 2v6M2 5l3 3 3-3" stroke="#DC2626" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
        }
      </svg>
      {Math.abs(value)}%
    </span>
  );
}

